from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/interview_practice/interview_lab.json").read_text(
        encoding="utf-8"
    )
)
import heapq, math

heap = []
for row in lab["catalog"]:
    if row["n"] < 10:
        continue
    key = (math.floor(row["total"] / row["n"] * 1000000000000.0 + 0.5), -row["id"])
    if len(heap) < 10:
        heapq.heappush(heap, key)
    elif key > heap[0]:
        heapq.heapreplace(heap, key)
print([-key[1] for key in sorted(heap, reverse=True)])

import heapq


def top_k(items, count):
    if type(count) is not int or count < 0:
        raise ValueError("K must be a nonnegative integer")
    if count == 0:
        return []
    heap = []
    for item_id, score in items:
        key = (round(score, 12), -item_id)
        if len(heap) < count:
            heapq.heappush(heap, key)
        elif key > heap[0]:
            heapq.heapreplace(heap, key)
    return [-negative_id for score, negative_id in sorted(heap, reverse=True)]


items = [(7, 4.2), (2, 4.2), (9, 4.1), (1, 4.3), (5, 4.2)]
answer = top_k(iter(items), 3)
oracle = sorted(items, key=lambda item: (-round(item[1], 12), item[0]))[:3]
assert answer == [item_id for item_id, score in oracle]
assert top_k(iter(items), 0) == [] and top_k(iter([]), 3) == []
print(*answer, answer[-1])

ছোট একটি নির্দেশিত (`Directed`) Graph হাতে কষে দেখলেই BFS-এর `Cycle` নিরাপত্তা ও পথ পুনর্গঠন পরিষ্কার হয়ে যায়।

> **উদাহরণ:** Graph-এর Edge-গুলো হলো $0 \to \{1, 2\}$, $1 \to \{3\}$, $2 \to \{3\}$ এবং ফেরার Edge $3 \to \{0\}$। উৎস `Node 0` থেকে BFS চালালে:
> - দূরত্ব দাঁড়ায় $\mathrm{dist} = [0, 1, 1, 2]$ (`Node 0, 1, 2, 3`-এর জন্য)।
> - $3 \to 0$ পথে `Cycle` থাকা সত্ত্বেও `0` আগে থেকেই `distance` ম্যাপে থাকায় লুপ কখনো অনন্তকাল ঘোরে না।
> - পুরো পথটিও চাইলে প্রতিটি `Node` প্রথমবার আবিষ্কারের সময় `parent[nxt] = cur` সংরক্ষণ করলেই শেষ থেকে উৎস পর্যন্ত পথ ফিরে পাওয়া যায়!

```python
from collections import deque

graph = {0: [1, 2], 1: [3], 2: [3], 3: [0]}
dist = {0: 0}
q = deque([0])
while q:
    u = q.popleft()
    for v in graph[u]:
        if v not in dist:
            dist[v] = dist[u] + 1
            q.append(v)
assert dist == {0: 0, 1: 1, 2: 1, 3: 2}
