from collections import deque


def dependency_order(graph):
    # Every node, including sinks, is a key in this adjacency dictionary.
    indegree = {node: 0 for node in graph}
    for neighbors in graph.values():
        for neighbor in neighbors:
            indegree[neighbor] += 1
    ready = deque(sorted(node for node, degree in indegree.items() if degree == 0))
    order = []
    while ready:
        node = ready.popleft()
        order.append(node)
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                ready.append(neighbor)
    return order, len(order) < len(graph)


graph = {0: [2], 1: [2], 2: [3], 3: []}
order, cyclic = dependency_order(graph)
positions = {node: index for index, node in enumerate(order)}
assert not cyclic and all(
    positions[node] < positions[neighbor] for node in graph for neighbor in graph[node]
)
changed = {node: neighbors.copy() for node, neighbors in graph.items()}
changed[3].append(1)
partial, has_cycle = dependency_order(changed)
print(*order, int(has_cycle), len(partial))

import math

coins, amount = [1, 3, 4], 6
dp = [0] + [math.inf] * amount
for subtotal in range(1, amount + 1):
    for coin in coins:
        if coin <= subtotal:
            # Infinite predecessor remains unreachable; no invalid shortcut.
            dp[subtotal] = min(dp[subtotal], dp[subtotal - coin] + 1)
answer = dp[amount] if math.isfinite(dp[amount]) else -1
print(answer)

import math


def minimum_coins(coins: list[int], amount: int) -> tuple[int, list[int]]:
    if type(amount) is not int or amount < 0:
        raise ValueError("Amount must be a nonnegative integer")
    if any(type(coin) is not int or coin <= 0 for coin in coins):
        raise ValueError("Coins must be positive integers")
    best = [0] + [math.inf] * amount
    choice = [None] * (amount + 1)
    for subtotal in range(1, amount + 1):
        for coin in coins:
            if coin <= subtotal and best[subtotal - coin] + 1 < best[subtotal]:
                best[subtotal] = best[subtotal - coin] + 1
                choice[subtotal] = coin
    if math.isinf(best[amount]):
        return -1, []
    path, remaining = [], amount
    while remaining:
        coin = choice[remaining]
        path.append(coin)
        remaining -= coin
    return int(best[amount]), path


count, path = minimum_coins([1, 3, 4], 6)
unreachable, empty_path = minimum_coins([4, 6], 5)
assert sum(path) == 6 and len(path) == count
assert minimum_coins([], 0) == (0, [])
print(count, *path, unreachable, len(empty_path))

from collections import deque

def level_sums(root):
    if root is None:
        return []
    pending = deque([root])
    totals = []
    while pending:
        level_total = 0
        for _ in range(len(pending)):
            value, left, right = pending.popleft()
            level_total += value
            for child in (left, right):
                if child is not None:
                    pending.append(child)
        totals.append(level_total)
    return totals

tree = (4, (1, None, (3, None, None)), (7, (6, None, None), (9, None, None)))
assert level_sums(None) == []
assert level_sums((-2, None, None)) == [-2]
print(*level_sums(tree))

def peak_rooms(intervals):
    events = []
    for start, end in intervals:
        if end < start:
            raise ValueError("end before start")
        if start != end:
            events.extend([(start, 1), (end, -1)])
    active = peak = 0
    for _, change in sorted(events):
        active += change
        peak = max(peak, active)
    return peak

assert peak_rooms([(0, 3), (3, 8)]) == 1
assert peak_rooms([(2, 2)]) == 0
print(peak_rooms([(0, 4), (1, 3), (3, 7), (3, 5)]))

